SELECT COUNT(DISTINCT c.customer_unique_id) AS result FROM customers c WHERE c.customer_unique_id IN (
  SELECT c2.customer_unique_id
  FROM customers c2
  JOIN orders o2 ON o2.customer_id = c2.customer_id
  WHERE o2.order_purchase_timestamp >= NOW() - INTERVAL '180 days'
);

SELECT COUNT(DISTINCT c.customer_unique_id) AS result FROM customers c WHERE c.customer_unique_id NOT IN (
  SELECT c2.customer_unique_id
  FROM customers c2
  JOIN orders o2 ON o2.customer_id = c2.customer_id
  WHERE o2.order_purchase_timestamp >= NOW() - INTERVAL '180 days'
);
